div.script:
document.addEventListener('DOMContentLoaded', function () {
    // 1. Obtener parámetros de URL (?plan=pyme-pro&billing=anual)
    var urlParams = new URLSearchParams(window.location.search);
    var currentPlan = urlParams.get('plan') || 'pyme-pro';
    var isMonthly = urlParams.get('billing') === 'mensual';
    var usersCount = 1;
    var implCost = 0;

    // Tarifas por plan: [precio_anual_mes, precio_mensual_mes]
    var planRates = {
        'emprendedor': { name: 'EMPRENDEDOR', color: '#0EA5E9', anual: 9.90, mensual: 11.90 },
        'pyme-pro': { name: 'PYME PRO', color: '#7D1A6A', anual: 14.90, mensual: 16.90 },
        'corporativo': { name: 'CORPORATIVO', color: '#2563EB', anual: 19.90, mensual: 21.90 }
    };

    if (!planRates[currentPlan]) {
        currentPlan = 'pyme-pro';
    }

    // Elementos DOM Paso 1
    var planTitleDisplay = document.getElementById('planTitleDisplay');
    var inputUsersCount = document.getElementById('inputUsersCount');
    var btnMinusUser = document.getElementById('btnMinusUser');
    var btnPlusUser = document.getElementById('btnPlusUser');
    var summaryBillingSwitch = document.getElementById('summaryBillingSwitch');
    var sumBtnAnual = document.getElementById('sumBtnAnual');
    var sumBtnMensual = document.getElementById('sumBtnMensual');

    var sumUsersCount = document.getElementById('sumUsersCount');
    var sumPlanBaseRate = document.getElementById('sumPlanBaseRate');
    var sumBaseTotal = document.getElementById('sumBaseTotal');
    var rowAnnualDiscount = document.getElementById('rowAnnualDiscount');
    var sumDiscountVal = document.getElementById('sumDiscountVal');
    var rowImplService = document.getElementById('rowImplService');
    var sumImplCost = document.getElementById('sumImplCost');
    var sumTotalMonthly = document.getElementById('sumTotalMonthly');
    var noteAnnualTotal = document.getElementById('noteAnnualTotal');
    var sumAnnualBilled = document.getElementById('sumAnnualBilled');

    // Elementos DOM Paso 2
    var stepConfigPlan = document.getElementById('stepConfigPlan');
    var stepBillingDetails = document.getElementById('stepBillingDetails');
    var btnGoToStep2 = document.getElementById('btnGoToStep2');
    var btnBackToStep1 = document.getElementById('btnBackToStep1');
    var crumbStep1 = document.getElementById('crumbStep1');

    var badgeStep2Users = document.getElementById('badgeStep2Users');
    var step2PlanNameDisplay = document.getElementById('step2PlanNameDisplay');
    var step2CycleLabel = document.getElementById('step2CycleLabel');
    var step2PlanSubtotal = document.getElementById('step2PlanSubtotal');
    var step2RowDiscount = document.getElementById('step2RowDiscount');
    var step2DiscountAmount = document.getElementById('step2DiscountAmount');
    var step2SubtotalNeto = document.getElementById('step2SubtotalNeto');
    var step2TaxAmount = document.getElementById('step2TaxAmount');
    var step2GrandTotal = document.getElementById('step2GrandTotal');
    var btnFinalizePurchase = document.getElementById('btnFinalizePurchase');

    function recalculate() {
        var planData = planRates[currentPlan];
        if (planTitleDisplay) {
            planTitleDisplay.textContent = planData.name;
            planTitleDisplay.style.color = planData.color;
        }

        var regularMonthlyRate = planData.mensual;
        var discountedMonthlyRate = planData.anual;
        var effectiveMonthlyRate = isMonthly ? regularMonthlyRate : discountedMonthlyRate;

        var baseTotalRegular = regularMonthlyRate * usersCount;
        var baseTotalEffective = effectiveMonthlyRate * usersCount;
        var discountMonthly = isMonthly ? 0 : (2.00 * usersCount);

        // Actualizar UI Paso 1
        if (sumUsersCount) sumUsersCount.textContent = usersCount;
        if (sumPlanBaseRate) sumPlanBaseRate.textContent = 'Tarifa base regular S/ ' + regularMonthlyRate.toFixed(2) + ' c/u';
        if (sumBaseTotal) sumBaseTotal.textContent = 'S/ ' + baseTotalRegular.toFixed(2);

        if (isMonthly) {
            if (summaryBillingSwitch) summaryBillingSwitch.classList.add('monthly');
            if (sumBtnMensual) sumBtnMensual.classList.add('active');
            if (sumBtnAnual) sumBtnAnual.classList.remove('active');
            if (rowAnnualDiscount) rowAnnualDiscount.style.display = 'none';
            if (noteAnnualTotal) noteAnnualTotal.innerHTML = 'Facturado mensualmente: S/ ' + (baseTotalEffective + implCost).toFixed(2) + '';
        } else {
            if (summaryBillingSwitch) summaryBillingSwitch.classList.remove('monthly');
            if (sumBtnAnual) sumBtnAnual.classList.add('active');
            if (sumBtnMensual) sumBtnMensual.classList.remove('active');
            if (rowAnnualDiscount) rowAnnualDiscount.style.display = 'flex';
            if (sumDiscountVal) sumDiscountVal.textContent = 'S/ -' + discountMonthly.toFixed(2);
            var annualBilled = (baseTotalEffective * 12) + implCost;
            if (noteAnnualTotal) noteAnnualTotal.innerHTML = '(*) Facturado anualmente: S/ ' + annualBilled.toFixed(2) + '';
        }

        if (sumTotalMonthly) sumTotalMonthly.textContent = 'S/ ' + baseTotalEffective.toFixed(2);

        // Actualizar UI Paso 2 (Checkout Fiscal)
        if (badgeStep2Users) badgeStep2Users.textContent = usersCount;
        if (step2PlanNameDisplay) step2PlanNameDisplay.textContent = 'Plan ' + planData.name.charAt(0) + planData.name.slice(1).toLowerCase();
        if (step2CycleLabel) step2CycleLabel.textContent = isMonthly ? 'por mes' : 'por año (12 meses)';

        var netBeforeTax = isMonthly ? (baseTotalEffective + implCost) : ((baseTotalEffective * 12) + implCost);
        var grossBeforeDiscount = isMonthly ? (baseTotalRegular + implCost) : ((baseTotalRegular * 12) + implCost);
        var totalDiscount = grossBeforeDiscount - netBeforeTax;

        if (step2PlanSubtotal) step2PlanSubtotal.textContent = 'S/ ' + grossBeforeDiscount.toFixed(2);
        if (isMonthly) {
            if (step2RowDiscount) step2RowDiscount.style.display = 'none';
        } else {
            if (step2RowDiscount) step2RowDiscount.style.display = 'flex';
            if (step2DiscountAmount) step2DiscountAmount.textContent = 'S/ -' + totalDiscount.toFixed(2);
        }

        var igv = netBeforeTax * 0.18;
        var grandTotal = netBeforeTax + igv;

        if (step2SubtotalNeto) step2SubtotalNeto.textContent = 'S/ ' + netBeforeTax.toFixed(2);
        if (step2TaxAmount) step2TaxAmount.textContent = 'S/ ' + igv.toFixed(2);
        if (step2GrandTotal) step2GrandTotal.textContent = 'S/ ' + grandTotal.toFixed(2);
    }

    // Stepper de Usuarios
    if (btnMinusUser) {
        btnMinusUser.addEventListener('click', function () {
            if (usersCount > 1) {
                usersCount--;
                inputUsersCount.value = usersCount;
                recalculate();
            }
        });
    }
    if (btnPlusUser) {
        btnPlusUser.addEventListener('click', function () {
            usersCount++;
            inputUsersCount.value = usersCount;
            recalculate();
        });
    }
    if (inputUsersCount) {
        inputUsersCount.addEventListener('change', function () {
            var val = parseInt(this.value, 10);
            usersCount = isNaN(val) || val < 1 ? 1 : val;
            this.value = usersCount;
            recalculate();
        });
    }

    // Switch Anual / Mensual
    if (summaryBillingSwitch) {
        summaryBillingSwitch.addEventListener('click', function () {
            isMonthly = !isMonthly;
            recalculate();
        });
    }
    if (sumBtnAnual) {
        sumBtnAnual.addEventListener('click', function (e) {
            e.stopPropagation();
            isMonthly = false;
            recalculate();
        });
    }
    if (sumBtnMensual) {
        sumBtnMensual.addEventListener('click', function (e) {
            e.stopPropagation();
            isMonthly = true;
            recalculate();
        });
    }

    // Opciones de Implementación
    var implCards = document.querySelectorAll('.impl-option-card');
    implCards.forEach(function (card) {
        card.addEventListener('click', function () {
            implCards.forEach(function (c) { c.classList.remove('selected'); });
            this.classList.add('selected');
            implCost = parseFloat(this.getAttribute('data-cost')) || 0;
            recalculate();
        });
    });

    // Navegación entre Paso 1 y Paso 2
    if (btnGoToStep2) {
        btnGoToStep2.addEventListener('click', function () {
            stepConfigPlan.style.display = 'none';
            stepBillingDetails.style.display = 'block';
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });
    }
    if (btnBackToStep1) {
        btnBackToStep1.addEventListener('click', function () {
            stepBillingDetails.style.display = 'none';
            stepConfigPlan.style.display = 'block';
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });
    }
    if (crumbStep1) {
        crumbStep1.addEventListener('click', function () {
            stepBillingDetails.style.display = 'none';
            stepConfigPlan.style.display = 'block';
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });
    }

    // Finalizar Compra con integración a Mercado Pago
    if (btnFinalizePurchase) {
        btnFinalizePurchase.addEventListener('click', function () {
            var form = document.getElementById('formCheckoutBilling');
            if (form && !form.checkValidity()) {
                form.reportValidity();
                return;
            }

            var originalText = btnFinalizePurchase.innerHTML;
            btnFinalizePurchase.disabled = true;
            btnFinalizePurchase.innerHTML = '<i class="fa fa-spinner fa-spin me-2"></i> Conectando con Mercado Pago...';

            var payload = {
                plan: currentPlan,
                billing: isMonthly ? 'mensual' : 'anual',
                users: usersCount,
                impl_cost: implCost,
                client_name: document.getElementById('inputClientName').value,
                email: document.getElementById('inputClientEmail').value,
                phone: document.getElementById('inputClientPhone').value,
                company_name: document.getElementById('inputCompanyName').value,
                fiscal_id: document.getElementById('inputFiscalId').value,
                subdomain: document.getElementById('inputSubdomain').value,
                address: document.getElementById('inputAddress').value,
                city: document.getElementById('inputCity').value,
                region: document.getElementById('selectRegion').value,
                amount_total: parseFloat(document.getElementById('step2GrandTotal').textContent.replace('S/ ', '')) || 0
            };

            fetch('/checkout/process_payment', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ params: payload })
            })
            .then(function (res) { return res.json(); })
            .then(function (data) {
                var result = data.result || data;
                if (result.status === 'success' || result.status === 'demo_success') {
                    window.location.href = result.redirect_url;
                } else {
                    alert(result.message || 'Ocurrió un error al procesar el pago. Por favor intente nuevamente.');
                    btnFinalizePurchase.disabled = false;
                    btnFinalizePurchase.innerHTML = originalText;
                }
            })
            .catch(function (err) {
                console.error('Error:', err);
                btnFinalizePurchase.disabled = false;
                btnFinalizePurchase.innerHTML = originalText;
                alert('Error de conexión al procesar el pago. Intente nuevamente.');
            });
        });
    }

    // Inicializar
    recalculate();
});
